/**
 * Story 1 · top-level layout.
 *
 * The camera lives in `useCamera`, created here with the measured size of the
 * board area, shared through `CameraApiContext`, and wired to the three
 * presentational pieces: the input surface, the zoom control and the hint.
 */
import { useRef } from 'react';
import { canZoomIn, canZoomOut, zoomPercent } from './canvas/camera';
import type { Size } from './canvas/camera';
import { BoardViewport } from './canvas/BoardViewport';
import { NavigationHint } from './canvas/NavigationHint';
import { ZoomControls } from './canvas/ZoomControls';
import { CameraApiContext, useCamera, useViewportSize } from './canvas/useCamera';

/**
 * The board, given the size of the area it occupies. Split out from `App` so
 * component tests can render the real tree with a fixed viewport size.
 */
export function BoardShell({ viewport }: { viewport: Size }) {
  const api = useCamera(viewport);
  const camera = api.camera;

  return (
    <CameraApiContext.Provider value={api}>
      <div className="board-root" data-testid="board-root">
        <BoardViewport />
        <ZoomControls
          zoomPercent={zoomPercent(camera)}
          canZoomIn={canZoomIn(camera)}
          canZoomOut={canZoomOut(camera)}
          onZoomIn={() => api.zoomStep('in')}
          onZoomOut={() => api.zoomStep('out')}
          onReset={() => api.reset()}
        />
        <NavigationHint visible={!api.hasNavigated} />
      </div>
    </CameraApiContext.Provider>
  );
}

export function App() {
  const stageRef = useRef<HTMLDivElement>(null);
  const viewport = useViewportSize(stageRef);

  return (
    <div ref={stageRef} className="board-root" data-testid="board-stage">
      <BoardShell viewport={viewport} />
    </div>
  );
}

/**
 * Story 1 · task 3 — the board input surface (design "viewport.input").
 *
 * Everything the board owns lives here: pointer-drag panning, the non-passive
 * wheel listener (React's `onWheel` is passive and cannot stop the page from
 * scrolling or zooming), Safari's `gesturestart`/`gesturechange` pinch, the
 * Ctrl/Cmd keyboard shortcuts, the dot grid and the world layer.
 */
import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from 'react';
import { GRID_SPACING_WORLD } from '../../shared/config';
import { worldToScreen } from './camera';
import { useCameraApi } from './useCamera';
import { useNavigationTestHooks } from './testHooks';

/** Pixels for one `deltaMode === LINE` wheel step. */
const WHEEL_LINE_PIXELS = 16;
/** Pixels for one `deltaMode === PAGE` wheel step. */
const WHEEL_PAGE_PIXELS = 400;

/** Dot radius in world units, so the dots stay attached to the board. */
const GRID_DOT_RADIUS_WORLD = 1.5;
const GRID_DOT_MIN_PX = 0.75;
const GRID_DOT_MAX_PX = 3;

/** Size of the origin crosshair, used as a stable pixel target in e2e. */
const MARKER_SIZE = 12;

const GRID_DOT_COLOR = '#b7bfcc';

export interface BoardViewportProps {
  children?: ReactNode;
}

function mod(value: number, range: number): number {
  return ((value % range) + range) % range;
}

function toWheelPixels(event: WheelEvent): { deltaX: number; deltaY: number } {
  const factor =
    event.deltaMode === 1
      ? WHEEL_LINE_PIXELS // DOM_DELTA_LINE
      : event.deltaMode === 2
        ? WHEEL_PAGE_PIXELS // DOM_DELTA_PAGE
        : 1;
  return { deltaX: event.deltaX * factor, deltaY: event.deltaY * factor };
}

/**
 * Only the board surface itself starts a drag. Objects added by later stories
 * sit in the world layer and can stop propagation without breaking panning.
 */
function isBoardSurface(target: EventTarget | null): boolean {
  const el = target as HTMLElement | null;
  return !!el && el.dataset.boardSurface === 'true';
}

interface ScaleEvent extends Event {
  scale?: number;
  clientX?: number;
  clientY?: number;
}

export function BoardViewport({ children }: BoardViewportProps) {
  const api = useCameraApi();
  useNavigationTestHooks();

  const { camera } = api;
  const surfaceRef = useRef<HTMLDivElement>(null);
  const apiRef = useRef(api);
  const panningRef = useRef(false);
  const gestureScaleRef = useRef(1);
  const [panning, setPanning] = useState(false);

  useEffect(() => {
    apiRef.current = api;
  }, [api]);

  useEffect(() => {
    const surface = surfaceRef.current;
    if (!surface) return;

    const relativePoint = (event: { clientX: number; clientY: number }) => {
      const rect = surface.getBoundingClientRect();
      return { x: event.clientX - rect.left, y: event.clientY - rect.top };
    };

    const onWheel = (event: WheelEvent) => {
      // Board-owned gesture: the page must never scroll or zoom instead.
      event.preventDefault();
      if (event.ctrlKey || event.metaKey) {
        // Zoom: raw deltaY drives the exponential factor; deltaMode is for
        // scroll distances, not zoom amounts.
        apiRef.current.wheel({
          deltaX: 0,
          deltaY: event.deltaY,
          ctrlOrMeta: true,
          point: relativePoint(event),
        });
        return;
      }
      const { deltaX, deltaY } = toWheelPixels(event);
      apiRef.current.wheel({
        deltaX,
        deltaY,
        ctrlOrMeta: false,
        point: relativePoint(event),
      });
    };

    const readScale = (event: Event): number | null => {
      const scale = (event as ScaleEvent).scale;
      if (typeof scale !== 'number' || !Number.isFinite(scale) || scale <= 0) return null;
      return scale;
    };

    const onGestureStart = (event: Event) => {
      event.preventDefault();
      gestureScaleRef.current = readScale(event) ?? 1;
    };

    const onGestureChange = (event: Event) => {
      event.preventDefault(); // Safari: gesturechange zooms the page otherwise
      const scale = readScale(event);
      if (scale === null) return;
      const factor = scale / gestureScaleRef.current;
      gestureScaleRef.current = scale;
      const gesture = event as ScaleEvent;
      // Safari supplies the pinch midpoint; without it, zoom around the
      // centre of the board area.
      const rect = surface.getBoundingClientRect();
      const gx = gesture.clientX;
      const gy = gesture.clientY;
      const point =
        typeof gx === 'number' && typeof gy === 'number'
          ? { x: gx - rect.left, y: gy - rect.top }
          : { x: rect.width / 2, y: rect.height / 2 };
      apiRef.current.pinch({ point, factor });
    };

    surface.addEventListener('wheel', onWheel, { passive: false });
    surface.addEventListener('gesturestart', onGestureStart, { passive: false });
    surface.addEventListener('gesturechange', onGestureChange, { passive: false });
    return () => {
      surface.removeEventListener('wheel', onWheel);
      surface.removeEventListener('gesturestart', onGestureStart);
      surface.removeEventListener('gesturechange', onGestureChange);
    };
  }, []);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (!event.ctrlKey && !event.metaKey) return;
      if (event.key === '=' || event.key === '+') {
        event.preventDefault();
        apiRef.current.zoomStep('in');
      } else if (event.key === '-' || event.key === '_') {
        event.preventDefault();
        apiRef.current.zoomStep('out');
      } else if (event.key === '0') {
        event.preventDefault();
        apiRef.current.reset();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    if (!isBoardSurface(event.target)) return;
    const surface = surfaceRef.current;
    if (!surface) return;
    try {
      surface.setPointerCapture(event.pointerId);
    } catch {
      // jsdom (and any engine without pointer capture) just skips it.
    }
    panningRef.current = true;
    setPanning(true);
    const rect = surface.getBoundingClientRect();
    api.beginPan({ x: event.clientX - rect.left, y: event.clientY - rect.top });
  };

  const onPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!panningRef.current) return;
    const surface = surfaceRef.current;
    if (!surface) return;
    const rect = surface.getBoundingClientRect();
    api.panMove({ x: event.clientX - rect.left, y: event.clientY - rect.top });
  };

  const endDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
    const surface = surfaceRef.current;
    if (surface && surface.hasPointerCapture?.(event.pointerId)) {
      try {
        surface.releasePointerCapture(event.pointerId);
      } catch {
        // ignore: capture may already be gone
      }
    }
    if (!panningRef.current) return;
    panningRef.current = false;
    setPanning(false);
    api.endPan();
  };

  const spacing = GRID_SPACING_WORLD * camera.zoom;
  const dotRadius = Math.min(
    GRID_DOT_MAX_PX,
    Math.max(GRID_DOT_MIN_PX, GRID_DOT_RADIUS_WORLD * camera.zoom),
  );
  const surfaceStyle: CSSProperties = {
    backgroundImage: `radial-gradient(circle at 0 0, ${GRID_DOT_COLOR} ${dotRadius}px, rgba(0, 0, 0, 0) ${dotRadius}px)`,
    backgroundSize: `${spacing}px ${spacing}px`,
    backgroundPosition: `${mod(-camera.x * camera.zoom, spacing)}px ${mod(
      -camera.y * camera.zoom,
      spacing,
    )}px`,
    cursor: panning ? 'grabbing' : 'default',
  };

  const origin = worldToScreen(camera, { x: 0, y: 0 });

  return (
    <div
      ref={surfaceRef}
      data-board-surface="true"
      data-testid="board-viewport"
      data-panning={panning ? 'true' : 'false'}
      className="board-viewport"
      style={surfaceStyle}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      onLostPointerCapture={endDrag}
    >
      <div
        data-testid="world-layer"
        data-camera={`${camera.x},${camera.y},${camera.zoom}`}
        className="world-layer"
        style={{
          transform: `scale(${camera.zoom}) translate(${-camera.x}px, ${-camera.y}px)`,
        }}
      >
        {children}
      </div>
      <div
        data-testid="origin-marker"
        data-marker="origin"
        aria-hidden="true"
        className="origin-marker"
        style={{
          left: `${origin.x - MARKER_SIZE / 2}px`,
          top: `${origin.y - MARKER_SIZE / 2}px`,
        }}
      />
    </div>
  );
}

/**
 * Story 1 · task 3 — the `useCamera` hook (design "Viewport input and
 * rendering").
 *
 * Owns the camera state and the navigation actions. It is deliberately free
 * of DOM knowledge: `BoardViewport` translates raw input events into these
 * calls. Camera updates are coalesced to at most one render per animation
 * frame, and an update that produces an identical camera (a click without
 * movement, a zoom at a limit) neither re-renders nor dismisses the hint.
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type RefObject,
} from 'react';
import { WHEEL_ZOOM_SENSITIVITY } from '../../shared/config';
import {
  panBy,
  resetCamera,
  zoomAt,
  zoomStep as zoomStepAt,
  type Camera,
  type Point,
  type Size,
} from './camera';

export interface WheelInput {
  /** Scroll delta in CSS pixels (deltaMode already converted). */
  deltaX: number;
  deltaY: number;
  /** True when Ctrl or Cmd is held: the gesture zooms instead of panning. */
  ctrlOrMeta: boolean;
  /** Pointer position relative to the board area. */
  point: Point;
}

export interface PinchInput {
  /** Pointer position relative to the board area. */
  point: Point;
  /** Scale ratio since the gesture started (Safari `gesturechange`). */
  factor: number;
}

export interface CameraApi {
  camera: Camera;
  hasNavigated: boolean;
  beginPan(p: Point): void;
  panMove(p: Point): void;
  endPan(): void;
  wheel(e: WheelInput): void;
  pinch(e: PinchInput): void;
  zoomStep(direction: 'in' | 'out'): void;
  reset(): void;
  /**
   * Jump to a camera. Only reachable through `window.__vidi6` in a test
   * build (see `testHooks.ts`); used by the e2e suite to travel to
   * UNBOUNDED_PAN_TESTED_EXTENT without a million pixels of dragging.
   */
  setCamera(cam: Camera): void;
}

/**
 * The standard view: the board's starting point (world origin) in the middle
 * of the board area at 100%. This is both the first view and what Reset view
 * returns to, so pressing Reset on a freshly loaded page changes nothing.
 */
const initialCamera = (viewport: Size): Camera => resetCamera(viewport);

function scheduleFrame(callback: () => void): number {
  if (typeof requestAnimationFrame === 'function') return requestAnimationFrame(callback);
  return setTimeout(callback, 0) as unknown as number;
}

function cancelFrame(id: number): void {
  if (typeof cancelAnimationFrame === 'function') cancelAnimationFrame(id);
  else clearTimeout(id);
}

export function useCamera(viewport: Size): CameraApi {
  const [camera, setCamera] = useState<Camera>(() => initialCamera(viewport));
  const [hasNavigated, setHasNavigated] = useState(false);

  // The ref is the source of truth so that several inputs inside one frame
  // compose correctly; React state is only the render mirror of it.
  const cameraRef = useRef<Camera>(initialCamera(viewport));
  const pendingRef = useRef<Camera | null>(null);
  const frameRef = useRef(0);
  const panRef = useRef<{ cam: Camera; x: number; y: number } | null>(null);
  const viewportRef = useRef<Size>(viewport);
  viewportRef.current = viewport;

  useEffect(
    () => () => {
      if (frameRef.current) cancelFrame(frameRef.current);
      frameRef.current = 0;
    },
    [],
  );

  const commit = useCallback((next: Camera) => {
    if (next === cameraRef.current) return;
    cameraRef.current = next;
    pendingRef.current = next;
    if (frameRef.current) return; // one render per frame: the latest wins
    frameRef.current = scheduleFrame(() => {
      frameRef.current = 0;
      const pending = pendingRef.current;
      pendingRef.current = null;
      if (!pending) return;
      setCamera(pending);
      setHasNavigated(true);
    });
  }, []);

  const beginPan = useCallback((p: Point) => {
    // Panning is measured from the camera captured at pointerdown, so the
    // board follows the pointer exactly no matter how many moves arrive.
    panRef.current = { cam: cameraRef.current, x: p.x, y: p.y };
  }, []);

  const panMove = useCallback(
    (p: Point) => {
      const pan = panRef.current;
      if (!pan) return;
      commit(panBy(pan.cam, p.x - pan.x, p.y - pan.y));
    },
    [commit],
  );

  const endPan = useCallback(() => {
    // Interruptions (pointerup, pointercancel, lostpointercapture) keep the
    // camera exactly where the last move left it.
    panRef.current = null;
  }, []);

  const wheel = useCallback(
    (e: WheelInput) => {
      if (e.ctrlOrMeta) {
        commit(
          zoomAt(
            cameraRef.current,
            e.point,
            Math.exp(-e.deltaY * WHEEL_ZOOM_SENSITIVITY),
          ),
        );
        return;
      }
      commit(panBy(cameraRef.current, -e.deltaX, -e.deltaY));
    },
    [commit],
  );

  const pinch = useCallback(
    (e: PinchInput) => {
      commit(zoomAt(cameraRef.current, e.point, e.factor));
    },
    [commit],
  );

  const zoomStep = useCallback(
    (direction: 'in' | 'out') => {
      commit(zoomStepAt(cameraRef.current, viewportRef.current, direction));
    },
    [commit],
  );

  const reset = useCallback(() => {
    commit(resetCamera(viewportRef.current));
  }, [commit]);

  const setCameraDirect = useCallback(
    (cam: Camera) => {
      commit(cam);
    },
    [commit],
  );

  return useMemo(
    () => ({
      camera,
      hasNavigated,
      beginPan,
      panMove,
      endPan,
      wheel,
      pinch,
      zoomStep,
      reset,
      setCamera: setCameraDirect,
    }),
    [
      camera,
      hasNavigated,
      beginPan,
      panMove,
      endPan,
      wheel,
      pinch,
      zoomStep,
      reset,
      setCameraDirect,
    ],
  );
}

/** Where the camera API is shared between the viewport and the overlays. */
export const CameraApiContext = createContext<CameraApi | null>(null);

export function useCameraApi(): CameraApi {
  const api = useContext(CameraApiContext);
  if (!api) {
    throw new Error('useCameraApi must be used inside a CameraApiContext.Provider');
  }
  return api;
}

/**
 * Track the size of the board area. A resize does not move content relative
 * to the top-left corner: only the viewport size changes (TC-07).
 */
export function useViewportSize(
  ref: RefObject<HTMLElement | null>,
): Size {
  const read = (): Size => {
    const el = ref.current;
    if (el && el.clientWidth > 0 && el.clientHeight > 0) {
      return { width: el.clientWidth, height: el.clientHeight };
    }
    if (typeof window !== 'undefined') {
      return { width: window.innerWidth, height: window.innerHeight };
    }
    return { width: 1280, height: 800 };
  };

  const [size, setSize] = useState<Size>(read);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(() => {
      const next = read();
      setSize((prev) =>
        prev.width === next.width && prev.height === next.height ? prev : next,
      );
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return size;
}

/**
 * Pure camera maths (see design "Camera maths").
 *
 * A Camera is `{ x, y, zoom }` where `x, y` is the world coordinate shown at
 * the top-left of the viewport and `zoom` is screen pixels per world unit.
 *
 * `screen = (world - camera.xy) * zoom`; `world = screen / zoom + camera.xy`.
 *
 * No DOM, no React: everything here is pure and testable in node. Every
 * mutation returns a *new* camera, or the *same* object when nothing would
 * change, so React can skip re-renders (and the navigation hint can latch on
 * object identity).
 */
import { ZOOM_MAX, ZOOM_MIN, ZOOM_STEP_FACTOR } from '../../shared/config';

export interface Camera {
  readonly x: number;
  readonly y: number;
  readonly zoom: number;
}

export interface Point {
  readonly x: number;
  readonly y: number;
}

export interface Size {
  readonly width: number;
  readonly height: number;
}

/**
 * Zoom levels produced by zoomStep snap to `ZOOM_STEP_FACTOR^n` when they are
 * within this relative tolerance of one, so that one step in followed by one
 * step out returns the bit-identical zoom level instead of drifting.
 */
const ZOOM_SNAP_TOLERANCE = 1e-9;

/** Zoom-to-percent scale (zoom 1 is shown as "100%"). */
const PERCENT = 100;

function clamp(value: number, min: number, max: number): number {
  return value < min ? min : value > max ? max : value;
}

/**
 * `ZOOM_STEP_FACTOR^n` computed as 5^n / 4^n with exact integer arithmetic
 * for the |n| reachable between ZOOM_MIN and ZOOM_MAX, avoiding the drift a
 * chain of `* 1.25` / `/ 1.25` operations would accumulate.
 */
function powerOfStep(n: number): number {
  const abs = Math.abs(n);
  let num = 1;
  let den = 1;
  for (let i = 0; i < abs; i++) {
    num *= 5;
    den *= 4;
  }
  return n >= 0 ? num / den : den / num;
}

/** Snap a zoom value to the nearest step ladder rung, if it is close enough. */
function snapToStepLadder(zoom: number): number {
  const n = Math.round(Math.log(zoom) / Math.log(ZOOM_STEP_FACTOR));
  const snapped = powerOfStep(n);
  if (!Number.isFinite(snapped) || snapped < ZOOM_MIN || snapped > ZOOM_MAX) return zoom;
  return Math.abs(snapped - zoom) <= ZOOM_SNAP_TOLERANCE * zoom ? snapped : zoom;
}

export function screenToWorld(cam: Camera, p: Point): Point {
  return { x: p.x / cam.zoom + cam.x, y: p.y / cam.zoom + cam.y };
}

export function worldToScreen(cam: Camera, p: Point): Point {
  return { x: (p.x - cam.x) * cam.zoom, y: (p.y - cam.y) * cam.zoom };
}

/**
 * Move the camera so content follows the pointer by `screenDx, screenDy`
 * CSS pixels. A zero-length drag returns the same camera object.
 */
export function panBy(cam: Camera, screenDx: number, screenDy: number): Camera {
  if (screenDx === 0 && screenDy === 0) return cam;
  return {
    x: cam.x - screenDx / cam.zoom,
    y: cam.y - screenDy / cam.zoom,
    zoom: cam.zoom,
  };
}

/**
 * Set the zoom to `newZoom` while keeping the world point currently under
 * `screenPoint` under `screenPoint`.
 */
function zoomToZoom(cam: Camera, screenPoint: Point, newZoom: number): Camera {
  if (newZoom === cam.zoom) return cam;
  const w = screenToWorld(cam, screenPoint);
  return {
    x: w.x - screenPoint.x / newZoom,
    y: w.y - screenPoint.y / newZoom,
    zoom: newZoom,
  };
}

/**
 * Zoom around a screen point. An invalid factor (not finite, or <= 0) leaves
 * the camera unchanged: input handlers must never be able to crash the board.
 */
export function zoomAt(cam: Camera, screenPoint: Point, factor: number): Camera {
  if (!Number.isFinite(factor) || factor <= 0) return cam;
  return zoomToZoom(cam, screenPoint, clamp(cam.zoom * factor, ZOOM_MIN, ZOOM_MAX));
}

/** One zoom step around the centre of the board area. */
export function zoomStep(cam: Camera, viewport: Size, direction: 'in' | 'out'): Camera {
  const centre: Point = { x: viewport.width / 2, y: viewport.height / 2 };
  const target =
    direction === 'in' ? cam.zoom * ZOOM_STEP_FACTOR : cam.zoom / ZOOM_STEP_FACTOR;
  return zoomToZoom(cam, centre, snapToStepLadder(clamp(target, ZOOM_MIN, ZOOM_MAX)));
}

/** 100% zoom with the board's starting point (world 0,0) centred. */
export function resetCamera(viewport: Size): Camera {
  return { x: -viewport.width / 2, y: -viewport.height / 2, zoom: 1 };
}

export function canZoomIn(cam: Camera): boolean {
  return cam.zoom < ZOOM_MAX;
}

export function canZoomOut(cam: Camera): boolean {
  return cam.zoom > ZOOM_MIN;
}

/** Current zoom as a whole-number percentage. */
export function zoomPercent(cam: Camera): number {
  return Math.round(cam.zoom * PERCENT);
}

/**
 * Product settings shared by the client (and, later, the Worker).
 * These are the "settings" named in the story designs: zoom limits, step size,
 * grid spacing. Changing a value here is the single place a designer can tune
 * the board without a redesign (PRD "Settings").
 */

/** Smallest zoom factor the board can reach (screen pixels per world unit). */
export const ZOOM_MIN = 0.1;

/** Largest zoom factor the board can reach. */
export const ZOOM_MAX = 4;

/** Multiplicative size of one zoom step (a step in multiplies by this). */
export const ZOOM_STEP_FACTOR = 1.25;

/** Wheel zoom sensitivity: zoom factor = exp(-deltaY * sensitivity). */
export const WHEEL_ZOOM_SENSITIVITY = 0.01;

/** Dot-grid spacing in world units. */
export const GRID_SPACING_WORLD = 24;

/** How far the unbounded-board requirement is tested (world units). */
export const UNBOUNDED_PAN_TESTED_EXTENT = 1_000_000;

/**
 * Story 1 · task 3 — test-only browser hook.
 *
 * `window.__vidi6.setCamera()` lets the e2e suite jump straight to
 * UNBOUNDED_PAN_TESTED_EXTENT (dragging a million pixels is impractical) and
 * lets it read the camera back to check the pointer invariant. The whole
 * effect body is dead code outside `MODE === 'test'`, so a production build
 * never installs the hook.
 */
import { useEffect } from 'react';
import type { Camera } from './camera';
import { useCameraApi } from './useCamera';

export interface Vidi6TestHooks {
  setCamera(cam: Camera): void;
  getCamera(): Camera;
}

declare global {
  interface Window {
    __vidi6?: Vidi6TestHooks;
  }
}

export function isTestMode(): boolean {
  return import.meta.env.MODE === 'test';
}

export function useNavigationTestHooks(): void {
  const api = useCameraApi();
  useEffect(() => {
    if (!isTestMode() || typeof window === 'undefined') return;
    // Re-assigned on every render so the hook always sees the current camera.
    window.__vidi6 = {
      setCamera: (cam: Camera) => api.setCamera(cam),
      getCamera: () => api.camera,
    };
  });
}

import { afterEach } from 'vitest';
import { cleanup } from '@testing-library/react';

// jsdom does not implement pointer capture; tests install their own stubs.
afterEach(() => {
  cleanup();
});

/**
 * Story 1 · task 6 — component tests for the viewport input surface
 * (TC-13 … TC-18, TC-29, TC-30 from the design's ui-component list).
 *
 * jsdom has no layout: instead of measuring pixels these tests assert the
 * DOM facts the renderer produces (the world layer transform and the camera
 * stamp) and the event-handling contract (preventDefault, state machine).
 * Real pixel alignment is covered by the Playwright suite.
 */
import { beforeEach, describe, expect, it } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { BoardShell } from '../../src/client/App';
import type { Camera, Size } from '../../src/client/canvas/camera';
import { NAVIGATION_HINT_TEXT } from '../../src/client/canvas/NavigationHint';
import { WHEEL_ZOOM_SENSITIVITY } from '../../src/shared/config';

const VIEWPORT: Size = { width: 800, height: 600 };

/** The standard view: world (0,0) centred in an 800x600 board area. */
const START: Camera = { x: -400, y: -300, zoom: 1 };

beforeEach(() => {
  cleanup();
});

function renderBoard(viewport: Size = VIEWPORT) {
  const utils = render(<BoardShell viewport={viewport} />);
  return {
    ...utils,
    surface: () => screen.getByTestId('board-viewport') as HTMLElement,
    world: () => screen.getByTestId('world-layer') as HTMLElement,
    camera: (): Camera => {
      const stamp = (screen.getByTestId('world-layer') as HTMLElement).dataset.camera;
      const [x, y, zoom] = (stamp ?? '').split(',').map(Number);
      return { x, y, zoom };
    },
  };
}

/** jsdom implements PointerEvent, but not pointer capture. */
function pointer(type: string, x: number, y: number): Event {
  const event = new MouseEvent(type, {
    bubbles: true,
    cancelable: true,
    clientX: x,
    clientY: y,
    button: 0,
  });
  Object.defineProperty(event, 'pointerId', { value: 1 });
  Object.defineProperty(event, 'pointerType', { value: 'mouse' });
  Object.defineProperty(event, 'isPrimary', { value: true });
  return event;
}

const nextFrames = () => new Promise((resolve) => setTimeout(resolve, 30));

describe('drag to pan (TC-13, TC-14, TC-29)', () => {
  it('TC-13: a drag moves the board by exactly the pointer delta and runs Idle -> Panning -> Idle', async () => {
    const board = renderBoard();
    const surface = board.surface();
    expect(board.camera()).toEqual(START);
    expect(surface.dataset.panning).toBe('false');

    fireEvent(surface, pointer('pointerdown', 400, 300));
    // State machine: a drag on empty board space is in the Panning state.
    expect(surface.dataset.panning).toBe('true');

    fireEvent(surface, pointer('pointermove', 600, 400));
    await waitFor(() => {
      expect(board.camera()).toEqual({ x: -600, y: -400, zoom: 1 });
    });
    // The world layer transform follows the camera: translate(-x, -y).
    expect(board.world().style.transform).toBe('scale(1) translate(600px, 400px)');
    // The grabbing-hand cursor is active while dragging.
    expect(surface.style.cursor).toBe('grabbing');

    fireEvent(surface, pointer('pointerup', 600, 400));
    expect(surface.dataset.panning).toBe('false');
    expect(surface.style.cursor).toBe('default');
    // No further change after the drag ended.
    expect(board.camera()).toEqual({ x: -600, y: -400, zoom: 1 });
  });

  it('TC-14: a cancelled drag freezes the camera and later moves are ignored', async () => {
    const board = renderBoard();
    const surface = board.surface();

    fireEvent(surface, pointer('pointerdown', 100, 100));
    fireEvent(surface, pointer('pointermove', 150, 140));
    await waitFor(() => {
      expect(board.camera()).toEqual({ x: -450, y: -340, zoom: 1 });
    });

    // The system interrupts the drag (alert, touch cancel, lost capture).
    fireEvent(surface, pointer('pointercancel', 150, 140));
    expect(surface.dataset.panning).toBe('false');

    // A move without a live drag must not move the board, however far.
    fireEvent(surface, pointer('pointermove', 900, 900));
    await nextFrames();
    expect(board.camera()).toEqual({ x: -450, y: -340, zoom: 1 });
  });

  it('TC-29: a click without movement leaves the camera and the hint alone', async () => {
    const board = renderBoard();
    const surface = board.surface();
    expect(screen.getByText(NAVIGATION_HINT_TEXT)).toBeTruthy();

    fireEvent(surface, pointer('pointerdown', 300, 300));
    fireEvent(surface, pointer('pointerup', 300, 300));
    await nextFrames();

    expect(board.camera()).toEqual(START);
    expect(screen.getByText(NAVIGATION_HINT_TEXT)).toBeTruthy();
  });
});

describe('wheel and gesture input (TC-15, TC-16, TC-17)', () => {
  it('TC-15: a plain scroll moves the board and prevents the page default', async () => {
    const board = renderBoard();
    const surface = board.surface();
    const before = board.camera();

    const event = new WheelEvent('wheel', {
      bubbles: true,
      cancelable: true,
      deltaX: 0,
      deltaY: 100,
      deltaMode: 0,
      clientX: 400,
      clientY: 300,
    });
    fireEvent(surface, event);

    // Scrolling down moves the viewport down the board: camera y grows by
    // deltaY / zoom.
    await waitFor(() => {
      expect(board.camera().y).toBeCloseTo(before.y + 100, 6);
    });
    expect(board.camera().zoom).toBe(1);
    expect(event.defaultPrevented).toBe(true);
  });

  it('TC-16: Ctrl + wheel zooms around the pointer and prevents the page default', async () => {
    const board = renderBoard();
    const surface = board.surface();
    const pointer = { x: 300, y: 200 };
    const before = board.camera();
    const worldBefore = {
      x: pointer.x / before.zoom + before.x,
      y: pointer.y / before.zoom + before.y,
    };

    const event = new WheelEvent('wheel', {
      bubbles: true,
      cancelable: true,
      deltaX: 0,
      deltaY: -100,
      deltaMode: 0,
      ctrlKey: true,
      clientX: pointer.x,
      clientY: pointer.y,
    });
    fireEvent(surface, event);

    const expectedZoom = Math.exp(100 * WHEEL_ZOOM_SENSITIVITY);
    await waitFor(() => {
      expect(board.camera().zoom).toBeCloseTo(expectedZoom, 6);
    });
    expect(event.defaultPrevented).toBe(true);

    // The world point that was under the pointer stayed under the pointer.
    const camera = board.camera();
    const worldAfter = {
      x: pointer.x / camera.zoom + camera.x,
      y: pointer.y / camera.zoom + camera.y,
    };
    expect(Math.abs(worldAfter.x - worldBefore.x)).toBeLessThan(1e-6);
    expect(Math.abs(worldAfter.y - worldBefore.y)).toBeLessThan(1e-6);
  });

  it('TC-17: a Safari gesturechange zooms by its scale ratio', async () => {
    const board = renderBoard();
    const surface = board.surface();

    const event = new Event('gesturechange', { bubbles: true, cancelable: true });
    Object.defineProperty(event, 'scale', { value: 2 });
    Object.defineProperty(event, 'clientX', { value: 400 });
    Object.defineProperty(event, 'clientY', { value: 300 });
    fireEvent(surface, event);

    await waitFor(() => {
      expect(board.camera().zoom).toBeCloseTo(2, 6);
    });
    expect(event.defaultPrevented).toBe(true);
  });
});

describe('keyboard shortcuts (TC-18)', () => {
  function key(keyName: string): KeyboardEvent {
    const event = new KeyboardEvent('keydown', {
      key: keyName,
      ctrlKey: true,
      bubbles: true,
      cancelable: true,
    });
    window.dispatchEvent(event);
    return event;
  }

  it('Ctrl + = zooms in one step, Ctrl + - back out, Ctrl + 0 resets', async () => {
    const board = renderBoard();
    // Start somewhere else, so that "reset" is a real change to observe.
    const FAR: Camera = { x: 12345, y: -9876, zoom: 1 };
    window.__vidi6?.setCamera(FAR);
    await waitFor(() => {
      expect(board.camera()).toEqual(FAR);
    });

    const zoomIn = key('=');
    await waitFor(() => {
      expect(board.camera().zoom).toBe(1.25);
    });
    expect(zoomIn.defaultPrevented).toBe(true);

    const zoomOut = key('-');
    await waitFor(() => {
      expect(board.camera().zoom).toBe(1);
    });
    // Zooming in and out around the same anchor round-trips exactly.
    expect(board.camera()).toEqual(FAR);
    expect(zoomOut.defaultPrevented).toBe(true);

    const reset = key('0');
    await waitFor(() => {
      expect(board.camera()).toEqual(START);
    });
    expect(reset.defaultPrevented).toBe(true);
    // The starting point is centred: world (0,0) maps to the viewport centre.
    expect(board.world().style.transform).toBe('scale(1) translate(400px, 300px)');
  });

  it('ignores keys without Ctrl or Cmd', async () => {
    const board = renderBoard();
    const plain = new KeyboardEvent('keydown', { key: '=', bubbles: true, cancelable: true });
    window.dispatchEvent(plain);
    await nextFrames();
    expect(board.camera()).toEqual(START);
  });
});

describe('scope of board gestures (TC-30)', () => {
  it('Ctrl + wheel over the zoom control does not zoom the board', async () => {
    const board = renderBoard();
    const controls = screen.getByTestId('zoom-controls');

    const event = new WheelEvent('wheel', {
      bubbles: true,
      cancelable: true,
      deltaY: -240,
      deltaMode: 0,
      ctrlKey: true,
    });
    fireEvent(controls, event);
    await nextFrames();

    // Outside the board the browser keeps its own behaviour: the event is not
    // cancelled, and the board camera never moved.
    expect(event.defaultPrevented).toBe(false);
    expect(board.camera()).toEqual(START);
  });
});

/**
 * Story 1 · task 7 — end-to-end navigation tests.
 *
 * Run against the real app served by `wrangler dev`, in Chromium, Firefox and
 * WebKit. Pixel facts are measured from the page (marker bounding box,
 * sampled screenshot pixels); the ±1 px tolerance comes from the design's
 * "Visual alignment tolerance for e2e".
 */
import { expect, test } from '@playwright/test';
import {
  expectDotAt,
  getCamera,
  gridGeometry,
  markerPosition,
  nearestDot,
  setCamera,
  settle,
  viewportSize,
  zoomLabel,
  type Camera,
  type Point,
} from './helpers/board';
import { GRID_SPACING_WORLD, UNBOUNDED_PAN_TESTED_EXTENT } from '../../src/shared/config';

/** Where a world point is painted on screen for the given camera. */
const project = (camera: Camera, world: Point): Point => ({
  x: (world.x - camera.x) * camera.zoom,
  y: (world.y - camera.y) * camera.zoom,
});

test('the first-use hint is shown and the first drag removes it', async ({ page }) => {
  await page.goto('/');
  const hint = page.getByTestId('navigation-hint');
  await expect(hint).toBeVisible();
  await expect(hint).toHaveText('Drag to move around · Ctrl/Cmd + scroll or pinch to zoom');

  await page.mouse.move(520, 360);
  await page.mouse.down();
  await page.mouse.move(560, 400, { steps: 6 });
  await page.mouse.up();

  await expect(hint).toHaveCount(0);
  // The hint does not come back for the rest of the visit.
  await page.mouse.move(560, 400);
  await page.mouse.down();
  await page.mouse.move(600, 420, { steps: 4 });
  await page.mouse.up();
  await settle(page);
  await expect(page.getByTestId('navigation-hint')).toHaveCount(0);
});

test('TC-23: a drag of (200,100) moves the marker and the dot grid by exactly that delta', async ({
  page,
}) => {
  await page.goto('/');
  await settle(page);

  const viewport = await viewportSize(page);
  const cameraBefore = await getCamera(page);
  const markerBefore = await markerPosition(page);

  // Reference points well away from the origin crosshair (which is itself
  // dark) so a "dot here" reading cannot be a false positive.
  const probes: Point[] = [
    { x: 300, y: 200 },
    { x: 980, y: 180 },
    { x: 1000, y: 500 },
    { x: 240, y: 480 },
  ];
  const dotsBefore = probes.map((probe) =>
    nearestDot(cameraBefore, GRID_SPACING_WORLD, probe),
  );
  for (const dot of dotsBefore) {
    await expectDotAt(page, dot);
  }

  await page.mouse.move(700, 300);
  await page.mouse.down();
  await page.mouse.move(900, 400, { steps: 10 });
  await page.mouse.up();
  await settle(page);

  // Camera fact: the drag moved the camera by exactly delta / zoom.
  const camera = await getCamera(page);
  expect(camera.zoom).toBe(1);
  expect(camera.x).toBeCloseTo(cameraBefore.x - 200, 6);
  expect(camera.y).toBeCloseTo(cameraBefore.y - 100, 6);

  // Marker fact: the board followed the pointer, so the world-origin marker
  // moved with it by exactly (+200,+100), ±1 px.
  const marker = await markerPosition(page);
  expect(Math.abs(marker.x - (markerBefore.x + 200))).toBeLessThanOrEqual(1);
  expect(Math.abs(marker.y - (markerBefore.y + 100))).toBeLessThanOrEqual(1);

  // Visual fact: each dot that was under a probe moved with the board, so it
  // is still painted within 1 px of where the camera says it must be. A grid
  // that lagged, or did not move at all, would be at least 4 px away here.
  for (let index = 0; index < probes.length; index += 1) {
    const world = {
      x: dotsBefore[index].x + cameraBefore.x,
      y: dotsBefore[index].y + cameraBefore.y,
    };
    const expected = project(camera, world);
    // Keep the sample inside the page; the probes are placed so this holds.
    expect(expected.x).toBeGreaterThan(4);
    expect(expected.y).toBeGreaterThan(4);
    expect(expected.x).toBeLessThan(viewport.width - 4);
    expect(expected.y).toBeLessThan(viewport.height - 4);
    await expectDotAt(page, expected);
  }
});

test('TC-24: Ctrl + scroll zooms about the pointer and the dot under it stays put', async ({
  page,
}) => {
  await page.goto('/');
  await settle(page);

  const cameraBefore = await getCamera(page);
  // Aim at a dot, so the "same dot" check has something to look at.
  const pointer = nearestDot(cameraBefore, GRID_SPACING_WORLD, { x: 360, y: 220 });
  await expectDotAt(page, pointer);

  await page.mouse.move(pointer.x, pointer.y);
  await page.keyboard.down('Control');
  await page.mouse.wheel(0, -120);
  await page.keyboard.up('Control');
  await settle(page);

  const camera = await getCamera(page);
  expect(camera.zoom).toBeGreaterThan(2); // one wheel notch at 0.01 sensitivity
  expect(camera.zoom).toBeLessThanOrEqual(4);

  // Visual fact: a dot is still painted at the pointer, within 1 px.
  await expectDotAt(page, pointer);

  // And the browser did not zoom the page instead.
  const scale = await page.evaluate(() => window.visualViewport?.scale ?? 1);
  expect(scale).toBe(1);
});

test('TC-25: the zoom-in button disables at 400% and the board stops zooming', async ({
  page,
}) => {
  await page.goto('/');
  await settle(page);

  const zoomIn = page.getByRole('button', { name: 'Zoom in' });
  const zoomOut = page.getByRole('button', { name: 'Zoom out' });
  await expect(zoomIn).toBeEnabled();
  await expect(zoomOut).toBeEnabled();
  expect(await zoomLabel(page)).toBe('100%');

  await zoomIn.click();
  await settle(page);
  expect(await zoomLabel(page)).toBe('125%');

  // Enough clicks to walk past the maximum, checking each state transition.
  for (let click = 0; click < 12; click += 1) {
    if (!(await zoomIn.isEnabled())) break;
    await zoomIn.click();
    await settle(page);
  }

  expect(await zoomLabel(page)).toBe('400%');
  await expect(zoomIn).toBeDisabled();
  const camera = await getCamera(page);
  expect(camera.zoom).toBe(4);

  // Clicking the disabled button (and the shortcut) changes nothing.
  await zoomIn.click({ force: true });
  await page.keyboard.press('Control+=');
  await settle(page);
  expect((await getCamera(page)).zoom).toBe(4);

  // Zooming out works again, one step at a time (400% / 1.25 = 320%).
  await zoomOut.click();
  await settle(page);
  expect(await zoomLabel(page)).toBe('320%');
  expect((await getCamera(page)).zoom).toBeCloseTo(4 / 1.25, 6);
});

test('TC-26: reset view recentres after a long jump at 400%', async ({ page }) => {
  await page.goto('/');
  await settle(page);

  await setCamera(page, { x: 12345, y: -9876, zoom: 4 });
  expect(await zoomLabel(page)).toBe('400%');
  const markerFar = await markerPosition(page);
  expect(Math.abs(markerFar.x)).toBeGreaterThan(100);

  await page.getByRole('button', { name: 'Reset view' }).click();
  await settle(page);

  expect(await zoomLabel(page)).toBe('100%');
  const viewport = await viewportSize(page);
  const marker = await markerPosition(page);
  const centre = { x: viewport.width / 2, y: viewport.height / 2 };
  expect(Math.abs(marker.x - centre.x)).toBeLessThanOrEqual(1);
  expect(Math.abs(marker.y - centre.y)).toBeLessThanOrEqual(1);

  const camera = await getCamera(page);
  expect(camera).toEqual({
    x: -viewport.width / 2,
    y: -viewport.height / 2,
    zoom: 1,
  });
});

test('TC-27: panning far from the origin keeps exact movement and grid spacing', async ({
  page,
}) => {
  await page.goto('/');
  await settle(page);

  const far = {
    x: UNBOUNDED_PAN_TESTED_EXTENT,
    y: -UNBOUNDED_PAN_TESTED_EXTENT,
    zoom: 2,
  };
  await setCamera(page, far);

  // Grid fact: the spacing on screen is GRID_SPACING_WORLD * zoom.
  const grid = await gridGeometry(page);
  expect(grid.spacing).toBeCloseTo(GRID_SPACING_WORLD * far.zoom, 6);

  const probes: Point[] = [
    { x: 400, y: 250 },
    { x: 820, y: 300 },
    { x: 1040, y: 560 },
  ];
  const dotsBefore = probes.map((probe) =>
    nearestDot(far, GRID_SPACING_WORLD, probe),
  );
  for (const dot of dotsBefore) {
    await expectDotAt(page, dot);
  }

  await page.mouse.move(640, 400);
  await page.mouse.down();
  await page.mouse.move(840, 500, { steps: 10 });
  await page.mouse.up();
  await settle(page);

  // Camera fact: still exact 1:1 tracking at 1e6 (2x zoom halves the world
  // distance for the same pointer distance).
  const camera = await getCamera(page);
  expect(camera.zoom).toBe(2);
  expect(camera.x).toBeCloseTo(far.x - 100, 6);
  expect(camera.y).toBeCloseTo(far.y - 50, 6);

  // Visual fact: the grid is still drawn correctly that far out.
  for (let index = 0; index < probes.length; index += 1) {
    const world = {
      x: dotsBefore[index].x / far.zoom + far.x,
      y: dotsBefore[index].y / far.zoom + far.y,
    };
    const expected = project(camera, world);
    expect(expected.x).toBeGreaterThan(4);
    expect(expected.y).toBeGreaterThan(4);
    await expectDotAt(page, expected);
  }
});

test('TC-31: board gestures drive the board and never zoom or scroll the page', async ({
  page,
}) => {
  await page.goto('/');
  await settle(page);

  const initial = await page.evaluate(() => ({
    scale: window.visualViewport?.scale ?? 1,
    dpr: window.devicePixelRatio,
    scrollX: window.scrollX,
    scrollY: window.scrollY,
    scrollHeight: document.documentElement.scrollHeight,
    clientHeight: document.documentElement.clientHeight,
  }));
  expect(initial.scrollHeight).toBe(initial.clientHeight); // nothing to scroll
  const start = await getCamera(page);

  // Plain scroll: the board pans by the scroll delta, the page does not move.
  await page.mouse.move(640, 400);
  await page.mouse.wheel(0, -240);
  await settle(page);
  const panned = await getCamera(page);
  expect(panned.zoom).toBe(1);
  expect(panned.y).toBeCloseTo(start.y - 240, 6);

  // Ctrl + scroll: the board zooms around the pointer, the page does not.
  const anchor = {
    x: 640 / panned.zoom + panned.x,
    y: 400 / panned.zoom + panned.y,
  };
  await page.keyboard.down('Control');
  await page.mouse.wheel(0, -20);
  await page.keyboard.up('Control');
  await settle(page);
  const zoomed = await getCamera(page);
  expect(zoomed.zoom).toBeGreaterThan(1.2);
  expect(zoomed.zoom).toBeLessThan(1.4);
  const anchorAfter = {
    x: 640 / zoomed.zoom + zoomed.x,
    y: 400 / zoomed.zoom + zoomed.y,
  };
  expect(Math.abs(anchorAfter.x - anchor.x)).toBeLessThan(1e-6);
  expect(Math.abs(anchorAfter.y - anchor.y)).toBeLessThan(1e-6);

  // Keyboard zoom and reset, from a known camera so the steps are checkable.
  await setCamera(page, { x: 0, y: 0, zoom: 1 });
  await page.keyboard.press('Control+=');
  await settle(page);
  expect((await getCamera(page)).zoom).toBe(1.25);

  await page.keyboard.press('Control+-');
  await settle(page);
  expect((await getCamera(page)).zoom).toBe(1);

  await page.keyboard.press('Control+0');
  await settle(page);
  const viewport = await viewportSize(page);
  expect(await getCamera(page)).toEqual({
    x: -viewport.width / 2,
    y: -viewport.height / 2,
    zoom: 1,
  });

  const after = await page.evaluate(() => ({
    scale: window.visualViewport?.scale ?? 1,
    dpr: window.devicePixelRatio,
    scrollX: window.scrollX,
    scrollY: window.scrollY,
  }));
  expect(after.scale).toBe(1); // never a page zoom
  expect(after.dpr).toBe(initial.dpr);
  expect(after.scrollX).toBe(0);
  expect(after.scrollY).toBe(0); // never a page scroll
});

